import { Graph } from 'graphlib';

export function dynamicMemoryGraph(memories) {
  const graph = new Graph();
  memories.forEach(memory => {
    const { id, type, connections } = memory;
    graph.setNode(id, { type });
    connections.forEach(connection => {
      const { targetId, weight } = connection;
      graph.setEdge(id, targetId, weight);
    });
  });
  return graph;
}

export function queryMemoryGraph(graph, query) {
  // Example query logic: find related nodes
  const results = graph.nodes().filter(node => graph.node(node).type === query.type);
  return results;
}